using Microsoft.AspNetCore.Mvc; using System.Text.Json.Nodes; using RaceDay.Mvc.Models; using RaceDay.Mvc.Services;
namespace RaceDay.Mvc.Controllers;
public class OrganiserController(RaceDayApiClient api):Controller {
 bool Guard()=>HttpContext.Session.GetString("Role")=="Organiser"&& !string.IsNullOrEmpty(HttpContext.Session.GetString("Token"));
 IActionResult Deny()=>RedirectToAction("Login","Account");
 public async Task<IActionResult> Index(){if(!Guard())return Deny();try{var events=await api.Get("api/events");ViewBag.Events=events;ViewBag.Count=events is JsonArray a?a.Count:0;return View();}catch(Exception e){ViewBag.Error=e.Message;return View();}}
 public async Task<IActionResult> Events(){if(!Guard())return Deny();try{ViewBag.Events=await api.Get("api/events");}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 [HttpGet] public IActionResult CreateEvent(){if(!Guard())return Deny();return View(new EventVm());}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> CreateEvent(EventVm m){if(!Guard())return Deny();if(!ModelState.IsValid)return View(m);try{if(m.BannerFile!=null){var upload=await api.Upload("api/uploads/event-banner",m.BannerFile);m.BannerImageURL=upload?["url"]?.ToString();}await api.Send("api/events",HttpMethod.Post,new{name=m.Name,description=m.Description,eventDate=m.EventDate,location=m.Location,distanceKm=m.DistanceKm,eventType=m.EventType,bannerImageURL=m.BannerImageURL});TempData["Success"]="Event created successfully.";return RedirectToAction(nameof(Events));}catch(Exception e){ModelState.AddModelError("",e.Message);return View(m);}}
 [HttpGet] public async Task<IActionResult> EditEvent(int id){if(!Guard())return Deny();try{var x=await api.Get($"api/events/{id}");if(x==null)return NotFound();return View("CreateEvent",new EventVm{EventID=id,Name=x["name"]?.ToString()??"",Description=x["description"]?.ToString(),EventDate=DateTime.TryParse(x["eventDate"]?.ToString(),out var d)?d:DateTime.Today,Location=x["location"]?.ToString()??"",DistanceKm=decimal.TryParse(x["distanceKm"]?.ToString(),out var km)?km:5,EventType=x["eventType"]?.ToString()??"Run",BannerImageURL=x["bannerImageURL"]?.ToString()});}catch(Exception e){TempData["Error"]=e.Message;return RedirectToAction(nameof(Events));}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> EditEvent(EventVm m){if(!Guard())return Deny();if(!ModelState.IsValid)return View("CreateEvent",m);try{if(m.BannerFile!=null){var u=await api.Upload("api/uploads/event-banner",m.BannerFile);m.BannerImageURL=u?["url"]?.ToString();}await api.Send($"api/events/{m.EventID}",HttpMethod.Put,new{name=m.Name,description=m.Description,eventDate=m.EventDate,location=m.Location,distanceKm=m.DistanceKm,eventType=m.EventType,bannerImageURL=m.BannerImageURL});TempData["Success"]="Event updated.";return RedirectToAction(nameof(Events));}catch(Exception e){ModelState.AddModelError("",e.Message);return View("CreateEvent",m);}}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> DeleteEvent(int id){if(!Guard())return Deny();try{await api.Send($"api/events/{id}",HttpMethod.Delete);TempData["Success"]="Event deleted.";}catch(Exception e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Events));}
 public async Task<IActionResult> Categories(int eventId){if(!Guard())return Deny();ViewBag.EventId=eventId;try{ViewBag.Categories=await api.Get($"api/events/{eventId}/categories");}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> AddCategory(CategoryVm m){if(!Guard())return Deny();try{await api.Send($"api/events/{m.EventID}/categories",HttpMethod.Post,new{name=m.Name,distanceKm=m.DistanceKm,maxParticipants=m.MaxParticipants});TempData["Success"]="Category added.";}catch(Exception e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Categories),new{eventId=m.EventID});}
 public async Task<IActionResult> Enrolments(int eventId){if(!Guard())return Deny();ViewBag.EventId=eventId;try{ViewBag.Enrolments=await api.Get($"api/events/{eventId}/enrolments");}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 public async Task<IActionResult> Results(int eventId){if(!Guard())return Deny();ViewBag.EventId=eventId;try{ViewBag.Enrolments=await api.Get($"api/events/{eventId}/enrolments");ViewBag.Results=await api.Get($"api/events/{eventId}/results");}catch(Exception e){ViewBag.Error=e.Message;}return View();}
 [HttpPost,ValidateAntiForgeryToken] public async Task<IActionResult> SaveResult(ResultVm m,int eventId){if(!Guard())return Deny();try{await api.Send($"api/enrolments/{m.EnrolmentID}/results",HttpMethod.Post,new{finishTime=m.FinishTime,position=m.Position});TempData["Success"]="Race result saved.";}catch(Exception e){TempData["Error"]=e.Message;}return RedirectToAction(nameof(Results),new{eventId});}
}
